// Indicator-lamp grammar: shape + word, never colour alone.
// state: 'ok' | 'fail' | 'wait' | 'unknown'
export function lamp(state, word) {
  return `<span class="lamp lamp--${state}"><i aria-hidden="true"></i>${word}</span>`;
}

const CONN = {
  checking: ['wait', 'Checking API'],
  up:       ['ok', 'Connected'],
  down:     ['fail', 'API unreachable'],
};

export function renderBadge(conn) {
  const [state, word] = CONN[conn];
  return `<span class="badge" role="status">${lamp(state, word)}</span>`;
}

