:root {
  color-scheme: dark;
  --bg:      oklch(0.18 0.012 250);
  --surface: oklch(0.215 0.012 250);
  --line:    oklch(0.30 0.012 250);
  --edge:    oklch(0.58 0.012 250);  /* control borders: >=3:1 on surface */
  --ink:     oklch(0.95 0.006 250);
  --muted:   oklch(0.74 0.012 250);
  --accent:  oklch(0.74 0.13 250);
  --on-accent: oklch(0.18 0.012 250);
  --ring:    oklch(0.82 0.11 250);
  --ok:      oklch(0.78 0.15 150);
  --fail:    oklch(0.72 0.18 25);
  --fail-bg: oklch(0.235 0.035 25);
  --wait:    oklch(0.82 0.13 85);
  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 400 0.875rem/1.55 var(--sans);
}
h1, h2 { margin: 0; font-weight: 600; }
h1 { font-size: 1rem; letter-spacing: 0.01em; }
h2 { font-size: 0.875rem; }
.mono { font-family: var(--mono); font-size: 0.8125rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.sr-only {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; }

/* The signature: indicator lamps. Shape carries the meaning, colour confirms it. */
.lamp { display: inline-flex; align-items: center; gap: 0.5rem; white-space: nowrap; }
.lamp i {
  flex: none; width: 0.625rem; height: 0.625rem; border-radius: 1px;
  transition: background-color 200ms ease-out, border-color 200ms ease-out;
}
.lamp--ok i      { background: var(--ok); }
.lamp--fail i    { background: var(--fail); transform: rotate(45deg) scale(0.9); }
.lamp--wait i    { border: 2px solid var(--wait); }
.lamp--unknown i { border: 2px dashed var(--muted); }

.bar {
  display: flex; align-items: center; gap: 1.5rem; flex-wrap: wrap;
  padding: 0.75rem 1.5rem;
  border-block-end: 1px solid var(--line);
}
.summary { margin: 0; font-size: 1rem; font-weight: 600; }
.summary .lamp i { width: 0.75rem; height: 0.75rem; }
.badge { margin-inline-start: auto; color: var(--muted); }

.notice {
  margin: 0; padding: 0.625rem 1.5rem;
  background: var(--fail-bg); border-block-end: 1px solid var(--line);
}
.notice .lamp { font-weight: 600; margin-inline-end: 0.25rem; }

main { padding: 1.5rem; max-width: 72rem; }
.toolbar {
  display: flex; align-items: center; justify-content: space-between;
  gap: 1rem; flex-wrap: wrap; margin-block-end: 0.75rem;
}
.new-run { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
.new-run label { color: var(--muted); }

select, .btn {
  min-height: 2.75rem; padding: 0 0.875rem;
  font: inherit; border-radius: 6px; cursor: pointer;
}
select {
  background: var(--surface); color: var(--ink);
  border: 1px solid var(--edge);
}
.btn { border: 1px solid transparent; font-weight: 500; }
.btn--primary { background: var(--accent); color: var(--on-accent); min-width: 7rem; }
.btn--primary:hover:not(:disabled) { background: oklch(0.80 0.12 250); }
.btn--quiet { background: transparent; color: var(--ink); border-color: var(--edge); min-width: 6.5rem; }
.btn--quiet:hover:not(:disabled) { background: var(--line); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled, select:disabled { cursor: not-allowed; opacity: 0.55; }

.msg { font-size: 0.8125rem; }
.msg--ok   { color: var(--ok); }
.msg--fail { color: var(--fail); }

.table-wrap {
  overflow-x: auto;
  background: var(--surface);
  border: 1px solid var(--line); border-radius: 8px;
}
table { width: 100%; min-width: 40rem; border-collapse: collapse; }
th, td {
  padding: 0 1rem; height: 3.25rem;
  text-align: start; white-space: nowrap;
  border-block-end: 1px solid var(--line);
}
thead th {
  position: sticky; top: 0; height: 2.5rem;
  background: var(--surface);
  color: var(--muted); font-size: 0.8125rem; font-weight: 500;
}
thead th.num { text-align: end; }
tbody th { font-weight: 400; }
tbody tr:last-child > * { border-block-end: 0; }
tbody tr:hover { background: oklch(0.24 0.012 250); }
tbody tr.is-failed { background: var(--fail-bg); }
.actions { text-align: end; }
.actions .msg { margin-inline-end: 0.75rem; }

.empty { height: 8rem; text-align: center; color: var(--muted); }
.skel {
  display: block; height: 0.75rem; width: 70%;
  border-radius: 3px; background: var(--line);
  animation: pulse 1.2s ease-in-out infinite alternate;
}
@keyframes pulse { to { opacity: 0.45; } }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; }
}
@media (max-width: 40rem) {
  .bar, main { padding-inline: 1rem; }
  .notice { padding-inline: 1rem; }
}

