};

const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
// Actions only against live data on a reachable API; the notice banner says why when off.
const offReason = () =>
  state.conn !== 'up' ? 'Unavailable: API unreachable' : state.sample ? 'Unavailable: showing sample data' : '';
const failure = (e) => (e instanceof Response ? `the API returned ${e.status}` : 'the API is unreachable');

function statusCell(s) {
  const [kind, word] = STATUS[s] || ['unknown', s || 'Unknown'];
  return lamp(kind, esc(word));
}

function row(r) {
  const msg = state.rowMsg[r.id];
  const busy = msg?.kind === 'wait';
  const off = offReason();
  return `<tr class="${r.status === 'failed' ? 'is-failed' : ''}">
    <th scope="row" class="mono">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td>${statusCell(r.status)}</td>
    <td class="mono num">${esc(r.started)}</td>
    <td class="mono num">${esc(r.duration)}</td>
    <td class="actions">
      ${msg && !busy ? `<span class="msg msg--${msg.kind}">${esc(msg.text)}</span>` : ''}
      <button class="btn btn--quiet" data-retry="${esc(r.id)}" data-focus="retry-${esc(r.id)}"
        ${busy || off ? 'disabled' : ''} ${off ? `title="${off}"` : ''}
        aria-label="Retry run ${esc(r.id)}">${busy ? 'Retrying…' : 'Retry'}</button>
    </td>
  </tr>`;
}

function skeletonRows() {
  return Array.from({ length: 4 }, () =>
    `<tr aria-hidden="true">${'<td><span class="skel"></span></td>'.repeat(6)}</tr>`).join('');
}

function body() {
  if (!state.runs) return skeletonRows();
  if (!state.runs.length) {
    return `<tr><td colspan="6" class="empty">${lamp('unknown', 'No runs yet.')} Start one with New run.</td></tr>`;
  }
  return state.runs.map(row).join('');
}

function summary() {
  if (!state.runs) return lamp('wait', 'Loading runs');
  const n = state.runs.length;
  const failed = state.runs.filter((r) => r.status === 'failed').length;
  const scope = `last ${n} ${n === 1 ? 'run' : 'runs'}`;
  return failed
    ? lamp('fail', `${failed} failed · ${scope}`)
    : lamp('ok', `All passing · ${scope}`);
}

function notice() {
  if (state.conn === 'down') {
    return `<p class="notice">${lamp('fail', 'Not connected to the pulse API.')}
      ${state.sample ? 'Showing sample runs, not live data.' : ''}
      Retry and New run are off until the API is reachable.</p>`;
  }
  if (state.sample) {
    return `<p class="notice">${lamp('fail', 'Runs could not be loaded.')}
      Showing sample runs, not live data.</p>`;
  }
  return '';
}

function newRunForm() {
  const services = [...new Set((state.runs || []).map((r) => r.service))];
  const busy = state.newRun?.kind === 'wait';
  const off = offReason() || (!services.length && 'Unavailable: no services known yet');
  return `<form class="new-run" id="new-run">
    <label for="service">Service</label>
    <select id="service" name="service" data-focus="service" ${off ? 'disabled' : ''}>
      ${services.map((s) => `<option>${esc(s)}</option>`).join('')}
    </select>
    <button class="btn btn--primary" data-focus="new-run" ${busy || off ? 'disabled' : ''}
      ${off ? `title="${off}"` : ''}>${busy ? 'Starting…' : 'New run'}</button>
    ${state.newRun && !busy ? `<span class="msg msg--${state.newRun.kind}">${esc(state.newRun.text)}</span>` : ''}
  </form>`;
}

export function render() {
  const focused = document.activeElement?.dataset?.focus;
  const selected = document.querySelector('#service')?.value;

  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <h1>pulse</h1>
      <p class="summary">${summary()}</p>
      ${renderBadge(state.conn)}
    </header>
    ${notice()}
    <main>
      <div class="toolbar">
        <h2 id="runs-title">Deploy runs</h2>
        ${newRunForm()}
      </div>
      <div class="table-wrap" tabindex="0" role="region" aria-labelledby="runs-title">
        <table aria-busy="${!state.runs}">
          <thead><tr>
            <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
            <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
            <th scope="col"><span class="sr-only">Actions</span></th>
          </tr></thead>
          <tbody>${body()}</tbody>
        </table>
      </div>
    </main>`;

  if (selected) document.querySelector('#service').value = selected;
  if (focused) document.querySelector(`[data-focus="${focused}"]`)?.focus();
}

function announce(text) {
  document.querySelector('#announce').textContent = text;
}

async function loadRuns() {
  try {
    state.runs = await listRuns();
    state.sample = false;
  } catch {
    state.runs = SAMPLE_RUNS;
    state.sample = true;
  }
  render();
}

async function onRetry(id) {
  state.rowMsg[id] = { kind: 'wait' };
  render();
  try {
    const res = await retryRun(id);
    if (!res.ok) throw res;
    state.rowMsg[id] = { kind: 'ok', text: 'Retry queued' };
    loadRuns();
  } catch (e) {
    state.rowMsg[id] = { kind: 'fail', text: `Retry failed: ${failure(e)}` };
  }
  announce(`Run ${id}: ${state.rowMsg[id].text}`);
  render();
}

async function onNewRun(service) {
  state.newRun = { kind: 'wait' };
  render();
  try {
    const res = await createRun({ service }); // ponytail: body shape assumed, confirm with the API ticket
    if (!res.ok) throw res;
    state.newRun = { kind: 'ok', text: `Run started for ${service}` };
    loadRuns();
  } catch (e) {
    state.newRun = { kind: 'fail', text: `New run failed: ${failure(e)}` };
  }
  announce(state.newRun.text);
  render();
}

// Delegated once, so re-renders don't need rebinding.
const app = document.querySelector('#app');
app.addEventListener('click', (e) => {
  const b = e.target.closest('[data-retry]');
  if (b && !b.disabled) onRetry(b.dataset.retry);
});
app.addEventListener('submit', (e) => {
  e.preventDefault();
  if (state.newRun?.kind !== 'wait') onNewRun(e.target.service.value);
});

render();
health()
  .then(() => { state.conn = 'up'; })
  .catch(() => { state.conn = 'down'; })
  .finally(render);
loadRuns();
